import 'package:flutter/material.dart'; import 'package:shared_preferences/shared_preferences.dart'; import '../models/task_item.dart';
class HomePage extends StatefulWidget{const HomePage({super.key});@override State<HomePage> createState()=>_HomePageState();}
class _HomePageState extends State<HomePage>{ final tasks=[TaskItem(title:'أذكار الصباح'),TaskItem(title:'أذكار المساء'),TaskItem(title:'قراءة 5 صفحات قرآن'),TaskItem(title:'استغفار 100 مرة'),TaskItem(title:'الصلاة على النبي ﷺ 100 مرة')]; @override void initState(){super.initState(); loadInitialState();} Future<void> loadInitialState() async {await checkNewDay(); await loadTasks();} Future<void> checkNewDay() async {final p=await SharedPreferences.getInstance(); final n=DateTime.now(); final today='${n.year}-${n.month}-${n.day}'; if(p.getString('last_day')!=today){for(int i=0;i<tasks.length;i++){await p.setBool('task_$i',false); tasks[i].done=false;} await p.setString('last_day',today);}} Future<void> loadTasks() async {final p=await SharedPreferences.getInstance(); for(int i=0;i<tasks.length;i++){tasks[i].done=p.getBool('task_$i')??false;} if(mounted)setState((){});} Future<void> saveTask(int i,bool v) async {final p=await SharedPreferences.getInstance(); await p.setBool('task_$i',v);} double get progress=>tasks.where((e)=>e.done).length/tasks.length; @override Widget build(BuildContext context)=>Padding(padding:const EdgeInsets.all(16),child:Column(children:[Card(child:Padding(padding:const EdgeInsets.all(16),child:Column(children:[const Text('التقدم اليومي',style:TextStyle(fontSize:20,fontWeight:FontWeight.bold)),const SizedBox(height:15),LinearProgressIndicator(value:progress,minHeight:12,borderRadius:BorderRadius.circular(10)),const SizedBox(height:10),Text('${(progress*100).toInt()}%',style:const TextStyle(fontSize:18,fontWeight:FontWeight.bold))]))),const SizedBox(height:20),Expanded(child:ListView.builder(itemCount:tasks.length,itemBuilder:(c,i)=>Card(child:CheckboxListTile(value:tasks[i].done,title:Text(tasks[i].title),activeColor:Theme.of(context).colorScheme.primary,onChanged:(v)async{if(v==null)return; setState(()=>tasks[i].done=v); await saveTask(i,v);})) ))]));}
